class VideoLazyLoader{constructor(){this.init()}init(){const e=document.querySelectorAll(".ppg-video-lazy");0!==e.length&&e.forEach(e=>{const t=e.querySelector(".ppg-video-play-button"),o=e.querySelector(".ppg-video-thumbnail");t&&t.addEventListener("click",()=>this.loadVideo(e)),o&&o.addEventListener("click",()=>this.loadVideo(e))})}loadVideo(e){const t=e.dataset.videoUrl;if(!t)return;e.classList.add("ppg-video-loading");const o=this.addAutoplayParam(t),a=document.createElement("iframe");a.src=o,a.title=e.querySelector(".ppg-video-thumbnail")?.alt||"Video",a.allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",a.allowFullscreen=!0,a.style.border="0",a.style.opacity="0",e.innerHTML="",e.appendChild(a),setTimeout(()=>{a.style.transition="opacity 0.3s ease",a.style.opacity="1",e.classList.remove("ppg-video-loading"),e.classList.add("ppg-video-loaded")},800),a.addEventListener("load",()=>{a.style.opacity="1",e.classList.remove("ppg-video-loading"),e.classList.add("ppg-video-loaded")})}addAutoplayParam(e){const t=e.includes("?")?"&":"?";return`${e}${t}autoplay=1&mute=1`}}"loading"===document.readyState?document.addEventListener("DOMContentLoaded",()=>{new VideoLazyLoader}):new VideoLazyLoader;
